  static string ScenarioAppIdentity(ScenarioApplication app){return (app.Executable??"")+"|"+(app.SteamId??"");}
  void BuildScenarioApplications(StackPanel target,string query) {
   target.Children.Clear();var available=games.Select(g=>new ScenarioApplication{Name=g.Name,Executable=g.Executable,SteamId=g.SteamId}).Concat(scenarioDraft.Applications).GroupBy(ScenarioAppIdentity,StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).Where(a=>a.Name.IndexOf(query??"",StringComparison.OrdinalIgnoreCase)>=0).OrderBy(a=>a.Name).ToList();
   foreach(var app in available){var selected=app;var row=Row();var check=new CheckBox{Content=app.Name,Foreground=text,IsEnabled=!busy&&!closing,IsChecked=scenarioDraft.Applications.Any(a=>String.Equals(ScenarioAppIdentity(a),ScenarioAppIdentity(app),StringComparison.OrdinalIgnoreCase)),Margin=new Thickness(0,8,0,8),ToolTip=String.IsNullOrEmpty(app.Executable)?"Steam "+app.SteamId:app.Executable};check.Checked+=(s,e)=>{if(busy||closing)return;if(!scenarioDraft.Applications.Any(a=>String.Equals(ScenarioAppIdentity(a),ScenarioAppIdentity(selected),StringComparison.OrdinalIgnoreCase))){if(scenarioDraft.Applications.Count>=32){check.IsChecked=false;Log("一个设置档最多关联 32 个应用程序。");return;}scenarioDraft.Applications.Add(new ScenarioApplication{Name=selected.Name,Executable=selected.Executable,SteamId=selected.SteamId});}};check.Unchecked+=(s,e)=>{if(!busy&&!closing)scenarioDraft.Applications.RemoveAll(a=>String.Equals(ScenarioAppIdentity(a),ScenarioAppIdentity(selected),StringComparison.OrdinalIgnoreCase));};row.Children.Add(check);target.Children.Add(row);}if(available.Count==0)target.Children.Add(Paragraph("尚未找到应用程序，可从游戏库读取或手动添加。",12,muted));
  }
