   foreach(var item in copy.Settings){var setting=item;var row=new Grid{Margin=new Thickness(0,10,0,4)};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(240)});var label=new CheckBox{Content=ScenarioRules.Title(setting.Setting)+(setting.Setting=="dpiStage"?" "+(Convert.ToInt32(((IDictionary<string,object>)setting.Value)["index"])+1):""),IsChecked=true,Foreground=text,VerticalAlignment=VerticalAlignment.Center};included.Add(label);row.Children.Add(label);FrameworkElement input;Func<object> getter;
    if(ScenarioRules.Boolean(setting.Setting)){var check=new CheckBox{IsChecked=(bool)setting.Value,Foreground=text,VerticalAlignment=VerticalAlignment.Center};input=check;getter=()=>check.IsChecked==true;}
    else{string value=setting.Setting=="eqLevels"?String.Join(", ",((System.Collections.IEnumerable)setting.Value).Cast<object>()):setting.Setting=="lightingColor"?"#"+String.Join("",((System.Collections.IEnumerable)setting.Value).Cast<object>().Select(v=>Convert.ToInt32(v).ToString("X2"))):setting.Setting=="dpiStage"?Convert.ToString(((IDictionary<string,object>)setting.Value)["dpi"]):Convert.ToString(setting.Value,CultureInfo.InvariantCulture);var box=FeatureText(value);input=box;getter=()=>{int number;if(setting.Setting=="lightingColor"){if(!System.Text.RegularExpressions.Regex.IsMatch(box.Text,"^#[0-9a-fA-F]{6}$"))throw new InvalidDataException("颜色请输入 #RRGGBB。");return Enumerable.Range(0,3).Select(i=>Int32.Parse(box.Text.Substring(1+i*2,2),NumberStyles.HexNumber,CultureInfo.InvariantCulture)).ToArray();}if(setting.Setting=="eqLevels"){var parts=box.Text.Split(',');var values=new List<int>();foreach(string part in parts){if(!Int32.TryParse(part.Trim(),NumberStyles.Integer,CultureInfo.InvariantCulture,out number))throw new InvalidDataException("均衡器需要 8 个逗号分隔的整数。");values.Add(number);}return values.ToArray();}if(!Int32.TryParse(box.Text,NumberStyles.Integer,CultureInfo.InvariantCulture,out number))throw new InvalidDataException(ScenarioRules.Title(setting.Setting)+"需要整数。");if(setting.Setting=="dpiStage")return new Dictionary<string,object>{{"index",((IDictionary<string,object>)setting.Value)["index"]},{"dpi",number}};return number;};}
    Grid.SetColumn(input,1);row.Children.Add(input);body.Children.Add(row);edits.Add(getter);
   }
   var note=Paragraph("",12,muted);body.Children.Add(note);var buttons=Row();buttons.Children.Add(Button("保存到设置档",()=>{try{var selected=new List<ScenarioSetting>();for(int i=0;i<copy.Settings.Count;i++)if(included[i].IsChecked==true)selected.Add(new ScenarioSetting{Setting=copy.Settings[i].Setting,Value=edits[i]()});var candidate=ScenarioRepository.CloneRaw(new ScenarioProfile{Devices=new List<ScenarioDeviceProfile>{copy}}).Devices[0];candidate.Settings=selected;ScenarioRules.Validate(new ScenarioProfile{Devices=new List<ScenarioDeviceProfile>{candidate}});int index=scenarioDraft.Devices.IndexOf(original);scenarioDraft.Devices[index]=candidate;scenarioMessage="本地目标值已编辑，请保存或手动应用设置档。";dialog.Close();ShowPage(page);}catch(Exception ex){note.Text=ex.Message;}},true));buttons.Children.Add(Button("取消",()=>dialog.Close()));body.Children.Add(buttons);dialog.Content=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};dialog.ShowDialog();
  }
  void EditScenarioAudio(string flow){if(busy)return;var original=scenarioDraft.Audio.FirstOrDefault(a=>a.Flow==flow);if(original==null)return;var dialog=new Window{Title="DELTA II-KJP · Windows 音频配置",Owner=this,Width=470,Height=340,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=bg,Foreground=text,ResizeMode=ResizeMode.NoResize};var body=new StackPanel{Margin=new Thickness(24)};body.Children.Add(Paragraph(original.Name,12,muted));var volume=FeatureText(original.Volume.ToString(CultureInfo.InvariantCulture));body.Children.Add(FeatureField("目标音量（0–100%）",volume));var mute=new CheckBox{Content="静音",IsChecked=original.Muted,Foreground=text,Margin=new Thickness(0,18,0,18)};body.Children.Add(mute);var message=Paragraph("原读数 "+original.ObservedVolumePercent.ToString("0.##",CultureInfo.InvariantCulture)+"% · 保存为整百分比目标。",11,muted);body.Children.Add(message);var buttons=Row();buttons.Children.Add(Button("保存到设置档",()=>{int value;if(!Int32.TryParse(volume.Text,NumberStyles.Integer,CultureInfo.InvariantCulture,out value)||value<0||value>100){message.Text="请输入 0 至 100 之间的整数。";return;}original.Volume=value;original.Muted=mute.IsChecked==true;scenarioMessage="Windows 音频目标已编辑，尚未应用。";dialog.Close();ShowPage(page);},true));buttons.Children.Add(Button("取消",()=>dialog.Close()));body.Children.Add(buttons);dialog.Content=body;dialog.ShowDialog();}
  ScenarioProfile PreparedScenario(){var copy=ScenarioRepository.CloneRaw(scenarioDraft);copy.Name=(copy.Name??"").Trim();ScenarioRules.Validate(copy);return copy;}
  void LoadScenarioFiles(){try{string warning;scenarioFiles=scenarioRepository.List(out warning);if(warning!=null)scenarioMessage=warning;}catch(Exception ex){scenarioFiles=new List<ScenarioProfile>();scenarioMessage="本地设置档目录无法读取："+ex.Message;}}
  void SaveOriginalScenario(){if(busy)return;try{var profile=PreparedScenario();profile.SavedAt=DateTime.Now;scenarioRepository.Save(profile);scenarioDraft=profile;LoadScenarioFiles();scenarioMessage="本地设置档已保存，尚未应用。";ShowPage(page);}catch(Exception ex){ScenarioError(ex);}}
  void ImportOriginalScenario(){if(busy)return;var dialog=new Microsoft.Win32.OpenFileDialog{Title="导入本地情境设置档",Filter="本版情境设置档 (*.rogscenario.json)|*.rogscenario.json|JSON 文件 (*.json)|*.json",CheckFileExists=true};if(dialog.ShowDialog(this)!=true)return;try{var profile=ScenarioRepository.Read(dialog.FileName);profile.Id=Guid.NewGuid().ToString("N");profile.SavedAt=DateTime.MinValue;scenarioDraft=profile;scenarioResults.Clear();scenarioMessage="已导入本地档，点击保存后写入本地库。设备不会自动应用。";ShowPage(page);}catch(Exception ex){ScenarioError(ex);}}
  void ExportOriginalScenario(){if(busy)return;var dialog=new Microsoft.Win32.SaveFileDialog{Title="导出本地情境设置档",Filter="本版情境设置档 (*.rogscenario.json)|*.rogscenario.json",FileName="scenario.rogscenario.json",DefaultExt=".rogscenario.json",AddExtension=true};if(dialog.ShowDialog(this)!=true)return;try{ScenarioRepository.Write(dialog.FileName,PreparedScenario());scenarioMessage="本地设置档已导出。";UpdateScenarioNotice();}catch(Exception ex){ScenarioError(ex);}}
  async Task ApplyOriginalScenarioAndSave(){if(busy||closing||render||ScenarioFeaturesActive)return;if(!PermitHardwareWrite())return;try{var profile=PreparedScenario();if(ScenarioRules.BuildPlan(profile).Count==0)throw new InvalidDataException("请选择至少一个已捕获的设备配置。");profile.SavedAt=DateTime.Now;scenarioRepository.Save(profile);scenarioDraft=profile;LoadScenarioFiles();scenarioResults.Clear();scenarioCancel=new CancellationTokenSource();busy=true;scenarioApplyTask=RunOriginalScenarioAsync(profile,scenarioCancel.Token);ShowPage(page);await scenarioApplyTask;}catch(Exception ex){ScenarioError(ex);}}
  async Task RunOriginalScenarioAsync(ScenarioProfile profile,CancellationToken cancel){await Task.Yield();try{scenarioMessage="设置档已保存；正在核对所有目标设备…";UpdateScenarioNotice();var results=await ScenarioExecutor.RunAsync(profile,PreflightScenario,SendScenarioSetting,cancel,result=>{scenarioResults.Add(result);scenarioMessage="正在应用 · "+scenarioResults.Count+" 项已处理 · "+result.Label+"："+result.Message;UpdateScenarioNotice();Log(result.Label+" · "+result.Message);});int confirmed=results.Count(r=>r.Confirmed),failed=results.Count(r=>r.Outcome=="failed"),unconfirmed=results.Count(r=>r.Outcome=="unconfirmed"),cancelled=results.Count(r=>r.Outcome=="cancelled");scenarioMessage="本地档已保存 · 已确认 "+confirmed+" / "+results.Count+" · 失败 "+failed+" · 未确认 "+unconfirmed+" · 未发送 "+cancelled+"。已完成的设置会保留。";Log(scenarioMessage);}catch(OperationCanceledException){scenarioMessage="应用已停止；本地设置档已保存。";Log(scenarioMessage);}catch(Exception ex){scenarioMessage="应用前核对未通过，未发送设置："+ex.Message;Log(scenarioMessage);}finally{scenarioApplyTask=null;if(scenarioCancel!=null){scenarioCancel.Dispose();scenarioCancel=null;}busy=false;if(!closing)ShowPage(page);}}
  async Task PreflightScenario(List<ScenarioCommand> commands,CancellationToken cancel){
   foreach(var target in commands.Where(c=>c.Source=="gear").GroupBy(c=>c.Kind+":"+c.DeviceId)){
    cancel.ThrowIfCancellationRequested();if(closing)throw new OperationCanceledException();var command=target.First();var reply=await gearWorker.Request<SdkReply>(new Dictionary<string,object>{{"op","read"},{"kind",command.Kind},{"deviceId",command.DeviceId}});if(!reply.ok)throw new InvalidOperationException(SdkError(reply.error));
    if(reply.data==null||OriginalStateText(reply.data,"deviceId","")!=command.DeviceId||!GearOnline(reply.data)||OriginalStateFlag(reply.data,"readbackConfirmed")!=true)throw new InvalidOperationException(command.Kind+" 目标离线或未确认。");foreach(var setting in target)if(!GearCanSet(reply.data,setting.Setting))throw new InvalidOperationException(command.Kind+" 当前不支持安全切换 "+ScenarioRules.Title(setting.Setting)+"。");
    var snapshot=GearMap(reply.data,"snapshot");var rate=target.FirstOrDefault(c=>c.Setting=="pollingRate");var sync=target.FirstOrDefault(c=>c.Setting=="motionSync");int effectiveRate;Int32.TryParse(rate==null?OriginalStateText(snapshot,"pollingRate",""):Convert.ToString(rate.Value),out effectiveRate);bool effectiveSync=sync==null?OriginalStateFlag(snapshot,"motionSync")==true:Object.Equals(sync.Value,true);
    if(command.Kind=="mouse"&&(rate!=null||sync!=null)&&effectiveRate==8000&&effectiveSync)throw new InvalidOperationException("8000 Hz 需要先关闭 Motion Sync。");var stage=target.FirstOrDefault(c=>c.Setting=="activeDpiStage");int count;if(stage!=null&&(!Int32.TryParse(OriginalStateText(snapshot,"dpiStageCount",""),out count)||(int)stage.Value>count))throw new InvalidOperationException("此 DPI 档位在当前硬件配置中未启用。");
    reply.data["capturedAt"]=DateTime.Now.ToString("HH:mm:ss");gearStates[command.Kind]=reply.data;
   }
   foreach(var target in commands.Where(c=>c.Source=="audio").GroupBy(c=>c.DeviceId)){cancel.ThrowIfCancellationRequested();if(closing)throw new OperationCanceledException();var command=target.First();var reply=await audioEndpointWorker.Request<SdkReply>(new Dictionary<string,object>{{"op","read"},{"flow",command.Flow},{"endpointId",command.DeviceId}});if(!reply.ok)throw new InvalidOperationException(SdkError(reply.error));if(reply.data==null||OriginalStateText(reply.data,"endpointId","")!=command.DeviceId||OriginalStateText(reply.data,"flow","")!=command.Flow||OriginalStateFlag(reply.data,"matchConfirmed")!=true||OriginalStateFlag(reply.data,"readbackConfirmed")!=true)throw new InvalidOperationException("Windows 音频目标不匹配或未确认。");audioEndpoints.RemoveAll(a=>OriginalStateText(a,"endpointId","")==command.DeviceId);audioEndpoints.Add(reply.data);}
   cancel.ThrowIfCancellationRequested();if(closing)throw new OperationCanceledException();
  }
  async Task<ScenarioApplyResult> SendScenarioSetting(ScenarioCommand command){if(closing)throw new OperationCanceledException();hardwareControlPolicy.Demand();if(render)throw new InvalidOperationException("预览窗口不能应用设备设置。");try{SdkReply reply;if(command.Source=="gear"){reply=await gearWorker.Request<SdkReply>(new Dictionary<string,object>{{"op","set"},{"kind",command.Kind},{"deviceId",command.DeviceId},{"setting",command.Setting},{"value",command.Value},{"experimental",true}});if(reply.ok&&reply.data!=null){if(OriginalStateText(reply.data,"deviceId","")!=command.DeviceId)throw new InvalidOperationException("设备读回目标不匹配。");reply.data["capturedAt"]=DateTime.Now.ToString("HH:mm:ss");gearStates[command.Kind]=reply.data;}}
   else{reply=await audioEndpointWorker.Request<SdkReply>(new Dictionary<string,object>{{"op","set"},{"flow",command.Flow},{"endpointId",command.DeviceId},{"setting",command.Setting},{"value",command.Value},{"userInitiated",true}});if(reply.ok&&reply.data!=null){if(OriginalStateText(reply.data,"endpointId","")!=command.DeviceId||OriginalStateText(reply.data,"flow","")!=command.Flow||OriginalStateFlag(reply.data,"matchConfirmed")!=true)throw new InvalidOperationException("音频端点读回目标不匹配。");audioEndpoints.RemoveAll(a=>OriginalStateText(a,"endpointId","")==command.DeviceId);audioEndpoints.Add(reply.data);}}
   if(!reply.ok)throw new InvalidOperationException(SdkError(reply.error));bool confirmed=OriginalStateFlag(reply.data,"writeConfirmed")==true;bool already=OriginalStateText(reply.data,"appliedState","")=="alreadySet";return new ScenarioApplyResult{Outcome=confirmed?(already?"alreadySet":"confirmed"):"unconfirmed",Message=confirmed?(already?"当前设置已相同，未重复发送":"设置已读回确认"):"命令已接受，设置读回尚未匹配"};
   }catch{if(command.Source=="gear")gearStates.Remove(command.Kind);else audioEndpoints.RemoveAll(a=>OriginalStateText(a,"endpointId","")==command.DeviceId);throw;}
  }
  void ShowScenarioResults(){var dialog=new Window{Title="情境设置档 · 应用结果",Owner=this,Width=820,Height=560,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=bg,Foreground=text};var body=new StackPanel{Margin=new Thickness(24)};body.Children.Add(Paragraph(scenarioMessage,13,text));foreach(var result in scenarioResults)body.Children.Add(Paragraph(result.Label+" · "+result.Message,12,result.Confirmed?green:muted));dialog.Content=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};dialog.ShowDialog();}
  void UpdateScenarioNotice(){if(scenarioNotice!=null&&page=="情境设置档")scenarioNotice.Text=scenarioMessage;}
  void ScenarioError(Exception ex){scenarioMessage=ex.Message;UpdateScenarioNotice();Log("情境设置档："+ex.Message);}
  public void OnScenarioNavigation(string nextPage){if(nextPage!="情境设置档"&&scenarioCancel!=null)scenarioCancel.Cancel();}
  public async Task StopScenarioFeaturesAsync(){if(scenarioCancel!=null)scenarioCancel.Cancel();var task=scenarioApplyTask;if(task!=null)try{await task;}catch{}}
 }
